#pragma once
// Version and build id of the running build of SSHTermaq.
//   version      : set in CMakeLists.txt (project(SSHTermaq VERSION x.y.z)), the only place to change it
//   build number : commit count of HEAD when built; the 4th part of the file version (x.y.z.<number>)
//   commit       : short hash of HEAD, with "-dirty" when built with uncommitted changes
//   build time   : link time of the executable, read from its PE header, so it changes on every build
// The first three come from st_build_info.h, generated by cmake/BuildInfo.cmake on every build.
#include <cstdint>
#include <string>

namespace st {

struct BuildInfo {
    std::string version;  // "1.0.0"
    int number = 0;       // 0 when built outside a git checkout
    std::string commit;   // "35de5d8", "35de5d8-dirty", or "unknown" outside a git checkout
    std::string time;     // UTC, ISO 8601 ("2026-10-15T10:16:49Z"); empty if unknown
};

/** Build info of the running executable. */
const BuildInfo& buildInfo();

/** One line for the log and --version: "1.0.0 (build 10, 35de5d8, 2026-10-15 10:16:49 UTC)". */
std::string describeBuild(const BuildInfo& info);

/** Seconds since 1970 as UTC ISO 8601 ("2026-10-15T10:16:49Z"); empty for 0. */
std::string isoUtc(std::int64_t unixSeconds);

}  // namespace st
